widget.solution:
def preorder(root):
    if root is None:
        return []
    return [root.val] + preorder(root.left) + preorder(root.right)


def inorder(root):
    if root is None:
        return []
    return inorder(root.left) + [root.val] + inorder(root.right)


def level_order(root):
    out = []
    q = deque([root] if root else [])
    while q:
        node = q.popleft()
        out.append(node.val)
        if node.left:
            q.append(node.left)
        if node.right:
            q.append(node.right)
    return out

widget.prelude:
from collections import deque

class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
    def __repr__(self):
        return f"Node({self.val!r})"

def build(values):
    """Build a tree from a level-order list with None gaps."""
    if not values or values[0] is None:
        return None
    it = iter(values)
    root = Node(next(it))
    q = deque([root])
    while q:
        node = q.popleft()
        for side in ("left", "right"):
            try:
                v = next(it)
            except StopIteration:
                return root
            if v is not None:
                child = Node(v)
                setattr(node, side, child)
                q.append(child)
    return root

def to_list(root):
    """The level-order list with None gaps, trailing Nones dropped."""
    out, q = [], deque([root])
    while q:
        node = q.popleft()
        if node is None:
            out.append(None)
            continue
        out.append(node.val)
        q.append(node.left)
        q.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out

widget.solution:
def evaluate(node):
    if node.left is None and node.right is None:
        return node.val
    a = evaluate(node.left)
    b = evaluate(node.right)
    if node.val == '+':
        return a + b
    if node.val == '-':
        return a - b
    if node.val == '*':
        return a * b
    return max(a, b)

